In MQL5, you can set your stop loss to be 1% of your trading balance programmatically. Here are several approaches:

## Method 1: Calculate Stop Loss Distance Based on 1% Risk

```mql5
//+------------------------------------------------------------------+
//| Calculate stop loss price based on 1% risk                       |
//+------------------------------------------------------------------+
double CalculateStopLoss(string symbol, ENUM_ORDER_TYPE orderType, double entryPrice, double riskPercent = 1.0)
{
   // Get account balance
   double balance = AccountInfoDouble(ACCOUNT_BALANCE);

   // Calculate risk amount (1% of balance)
   double riskAmount = balance * (riskPercent / 100.0);

   // Get symbol information
   double tickSize = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_SIZE);
   double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
   double lotSize = 1.0; // You need to define your lot size

   // Calculate points for stop loss
   double stopLossPoints = (riskAmount / (lotSize * tickValue)) * tickSize;

   // Calculate stop loss price based on order type
   double stopLossPrice = 0;
   if(orderType == ORDER_TYPE_BUY)
   {
      stopLossPrice = entryPrice - stopLossPoints;
   }
   else if(orderType == ORDER_TYPE_SELL)
   {
      stopLossPrice = entryPrice + stopLossPoints;
   }

   return NormalizeDouble(stopLossPrice, (int)SymbolInfoInteger(symbol, SYMBOL_DIGITS));
}
```

## Method 2: Calculate Lot Size Based on Stop Loss Distance and 1% Risk

This is often more practical - you define your stop loss distance based on technical analysis, then calculate the appropriate lot size:

```mql5
//+------------------------------------------------------------------+
//| Calculate lot size based on risk percentage and stop loss        |
//+------------------------------------------------------------------+
double CalculateLotSize(string symbol, double stopLossPoints, double riskPercent = 1.0)
{
   // Get account information
   double balance = AccountInfoDouble(ACCOUNT_BALANCE);
   double riskAmount = balance * (riskPercent / 100.0);

   // Get symbol information
   double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
   double minLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MIN);
   double maxLot = SymbolInfoDouble(symbol, SYMBOL_VOLUME_MAX);
   double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);

   // Calculate lot size
   double lotSize = riskAmount / (stopLossPoints * tickValue);

   // Normalize lot size
   lotSize = MathFloor(lotSize / lotStep) * lotStep;

   // Ensure lot size is within limits
   if(lotSize < minLot) lotSize = minLot;
   if(lotSize > maxLot) lotSize = maxLot;

   return NormalizeDouble(lotSize, 2);
}
```

## Method 3: Complete Trading Function with 1% Risk Management

```mql5
//+------------------------------------------------------------------+
//| Place order with 1% risk management                              |
//+------------------------------------------------------------------+
bool PlaceOrderWithRiskManagement(string symbol, ENUM_ORDER_TYPE orderType, double stopLossDistance, double riskPercent = 1.0)
{
   MqlTradeRequest request = {};
   MqlTradeResult result = {};

   // Get current price
   double price = 0;
   if(orderType == ORDER_TYPE_BUY)
      price = SymbolInfoDouble(symbol, SYMBOL_ASK);
   else if(orderType == ORDER_TYPE_SELL)
      price = SymbolInfoDouble(symbol, SYMBOL_BID);

   // Calculate stop loss price
   double stopLossPrice = 0;
   if(orderType == ORDER_TYPE_BUY)
      stopLossPrice = price - stopLossDistance;
   else if(orderType == ORDER_TYPE_SELL)
      stopLossPrice = price + stopLossDistance;

   // Calculate lot size based on 1% risk
   double lotSize = CalculateLotSize(symbol, stopLossDistance, riskPercent);

   // Prepare trade request
   request.action = TRADE_ACTION_DEAL;
   request.symbol = symbol;
   request.volume = lotSize;
   request.type = orderType;
   request.price = price;
   request.sl = stopLossPrice;
   request.tp = 0; // Set your take profit as needed
   request.deviation = 10;
   request.magic = 123456; // Your magic number
   request.comment = "1% Risk Trade";

   // Send order
   if(!OrderSend(request, result))
   {
      Print("OrderSend error: ", GetLastError());
      return false;
   }

   return true;
}
```

## Method 4: Using CTrade Class (Simplified)

```mql5
#include <Trade\Trade.mqh>

CTrade trade;

//+------------------------------------------------------------------+
//| Open position with 1% risk                                       |
//+------------------------------------------------------------------+
bool OpenPositionWithRisk(string symbol, ENUM_ORDER_TYPE orderType, double stopLossPoints, double riskPercent = 1.0)
{
   // Calculate lot size
   double balance = AccountInfoDouble(ACCOUNT_BALANCE);
   double riskAmount = balance * (riskPercent / 100.0);
   double tickValue = SymbolInfoDouble(symbol, SYMBOL_TRADE_TICK_VALUE);
   double lotSize = riskAmount / (stopLossPoints * tickValue);

   // Normalize lot size
   double lotStep = SymbolInfoDouble(symbol, SYMBOL_VOLUME_STEP);
   lotSize = MathFloor(lotSize / lotStep) * lotStep;

   // Get current price
   double price = (orderType == ORDER_TYPE_BUY) ? 
                  SymbolInfoDouble(symbol, SYMBOL_ASK) : 
                  SymbolInfoDouble(symbol, SYMBOL_BID);

   // Calculate SL price
   double sl = (orderType == ORDER_TYPE_BUY) ? 
               price - stopLossPoints : 
               price + stopLossPoints;

   // Open position
   if(orderType == ORDER_TYPE_BUY)
      return trade.Buy(lotSize, symbol, price, sl, 0, "1% Risk");
   else
      return trade.Sell(lotSize, symbol, price, sl, 0, "1% Risk");
}
```

## Usage Example:

```mql5
void OnTick()
{
   // Example: Open buy position with 50 points stop loss and 1% risk
   double stopLossDistance = 50 * SymbolInfoDouble(_Symbol, SYMBOL_POINT);

   if(OpenPositionWithRisk(_Symbol, ORDER_TYPE_BUY, stopLossDistance, 1.0))
   {
      Print("Position opened with 1% risk");
   }
}
```

**Important Notes:**
1. Always check broker's minimum/maximum lot sizes
2. Consider spread and slippage in your calculations
3. Use `AccountInfoDouble(ACCOUNT_EQUITY)` instead of balance if you want to include floating P/L
4. Test thoroughly on a demo account first
5. Remember that this calculates position size based on stop loss distance, not the other way around

